python3 - <<'PY'
import os,re
def imports(m):
    p=m.replace('.','/')+'.lean'
    return re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)',open(p).read(),re.M) if os.path.exists(p) else []
seen,st=set(),['AlgebraicJacobian']
while st:
    m=st.pop()
    if m not in seen: seen.add(m); st+=imports(m)
allm=set()
for root,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'): allm.add(os.path.join(root,f)[:-5].replace('/','.'))
allm.add('AlgebraicJacobian')
print(f'rooted {len(seen)} of {len(allm)}; unrooted {len(allm-seen)}')
for u in sorted(allm-seen): print('  ',u)
# headline reachability
seen2,st2=set(),['AlgebraicJacobian.Jacobian']
while st2:
    m=st2.pop()
    if m not in seen2: seen2.add(m); st2+=imports(m)
print(f'headline reaches {len(seen2)} of {len(allm)-1} project modules')
PY
